import z3,itertools,time

def check(t,rs,ne,timeout=10000):
 k=t
 X=[];n=0
 for r in rs:
  X.append(sum(1<<v for v in range(n,n+k-r)));n+=k-r
 n+=ne
 E=[]
 for i,r in enumerate(rs):
  out=[v for v in range(n) if not (X[i]>>v&1)]
  E += [X[i]|sum(1<<v for v in R) for R in itertools.combinations(out,r)]
 E=list(set(E));x=[z3.Bool('x%d'%i) for i in range(len(E))]
 s=z3.Solver();s.set(timeout=timeout)
 for i,a in enumerate(E):
  for j in range(i):
   if not a&E[j]:s.add(z3.Or(z3.Not(x[i]),z3.Not(x[j])))
 for C in itertools.combinations(range(n),t-1):
  c=sum(1<<v for v in C)
  s.add(z3.Or([x[i] for i,a in enumerate(E) if not a&c]))
 ans=s.check()
 if ans==z3.sat:
  chosen=[a for i,a in enumerate(E) if z3.is_true(s.model()[x[i]])]
  print('FOUND',rs,ne,[[v for v in range(n) if a>>v&1] for a in chosen],flush=True)
 return str(ans)

